]$ai_catalog_patch$::jsonb) loop
    select id,definition_kind into prompt_uuid,existing_kind from shared.ai_prompts
      where app='bob' and prompt_key=item->>'key' for update;
    if prompt_uuid is null or existing_kind<>item->>'kind' then
      raise exception 'readiness_catalog_definition_mismatch: %',item->>'key';
    end if;
    select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prompt_uuid;
    insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,
      metadata,content,definition,flow,available_variables)
    values(prompt_uuid,next_version,item->>'kind',1,item->'metadata',item->>'content',item->'definition','',item->'variables')
    returning id into version_uuid;
    activation := activation || jsonb_build_object(item->>'key',version_uuid::text);
  end loop;
  for item in select value from jsonb_array_elements($tool_policy_patch$[
  {
    "name": "design_project_cad",
    "description": "Design and independently review CAD from the current purpose-appropriate selected Solution.",
    "how_to": "Read the selected Solution and its visible design_intent, linked original images and prior choices. The server assesses readiness for this output before design: construction geometry needs supported, settled controlling choices; a form-only exploratory sketch may defer explicit issues outside its purpose. An unavailable source or missing required feature is not waived by a simplified concept. Reuse prior choices and delegation. Read current construction drafts and check their exact revision. Pass that construction Artifact ID as artifact_id to draw its exact geometry. The same pinned intent, required features, materials, checks and original pixels reach the independent reviewer. Only save_cad_design persists the approved candidate; verify the saved receipt, exact revision, work link and readback. Correct construction issues in the checkpoint. Concept review never certifies strength or site fit.",
    "schema_version": 3,
    "always_load": false,
    "preload_phases": [
      "design"
    ],
    "active": true
  },
  {
    "name": "save_construction_draft",
    "description": "Save or revise a versioned construction with parts, exact materials and typed joints, without rendering.",
    "how_to": "Read the selected Solution, its visible design_intent and current drafts and catalog revisions first. Resolve consequential geometry-dependent choices through expert advice and actual selections; reuse prior decisions and delegation. The server blocks construction save when canonical intent or supported controlling choices are missing. Preserve stable Artifact, assembly, part and joint IDs. Supply the complete CAD parameter plan; the server computes values and rejects unknown controlling dimensions. Joint methods are design choices, not checked strength or hardware. Open questions stay explicit. A draft receipt is not a drawing or purchase receipt. Derive spans and positions from shared dimension nodes. Check the saved exact revision and correct reported IDs with another revision. Compare bounds and required features with the pinned Solution. A checked concept is not fabrication approval. For a drawing pass this checked construction Artifact ID to design_project_cad and verify the drawing save/link receipts and exact readback.",
    "schema_version": 1,
    "always_load": false,
    "preload_phases": [],
    "active": true
  },
  {
    "name": "save_project_solution",
    "description": "Create or revise a visible solution with design intent, references and advised decisions.",
    "how_to": "Read the current solution, selected target, linked images and prior decisions first. Preserve their exact scope and revisions. Record purpose, use, form/orientation and required features in design_intent. For each consequential choice record relevant alternatives, your supported recommendation, basis, consequences, chooser and actual selected direction; delegation is a mandate, not a chosen direction. Reuse prior owner decisions and explicit delegation. Resolve geometry-dependent technical questions through research and advice before construction, while an exploratory sketch may explicitly defer issues outside its purpose. Images supply intent, not measured dimensions. source_media_id names an accessible project reference. Explicit null source_media_id or design_intent clears that field; omitted fields on a legacy call preserve their previous values. Null design_intent remains unassessed and cannot establish readiness. A solution receipt records a proposal or design choice, not measured truth, target selection or structural approval.",
    "schema_version": 2,
    "always_load": false,
    "preload_phases": [],
    "active": true
  }
]$tool_policy_patch$::jsonb) loop
    update bob.tool_catalog set description=item->>'description',how_to=item->>'how_to',
      schema_version=(item->>'schema_version')::integer where name=item->>'name';
    if not found then raise exception 'readiness_catalog_tool_missing: %',item->>'name'; end if;
  end loop;
  perform shared.activate_ai_catalog('bob',activation);
end $readiness_catalog$;
commit;
